files=['README.md','docs/api.md','docs/architecture.md','docs/database.md','docs/roadmap.md','docs/feedback/2026-11-11-m7-frontend-handoff.md']
for f in files:
    s=open(f).read()
    links=re.findall(r'\[[^\]]*\]\(([^)]+)\)', s)
