          "description": "请求 ID，错误响应体中的 request_id 与之一致",
          "schema": {
            "type": "string"
          }
        },
        "Cache-Control": {
          "description": "固定 `no-cache`，避免中间层缓存 SSE 帧",
          "schema": {
            "type": "string",
            "enum": [
              "no-cache"
            ]
          }
        },
        "X-Accel-Buffering": {
          "description": "固定 `no`，关闭 Nginx 等反向代理的响应缓冲",
          "schema": {
            "type": "string",
            "enum": [
              "no"
            ]
          }
        }
      }
    },
    "400": {
      "description": "回放事件超过 1000 条（`replay_too_large`）：请改用 `GET /runs/{id}/events?after_seq=` 分页回放，或传入更接近的 `after_seq`",
